import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { createSpaceHandler } from "../handlers/createSpaceHandler";
import type { ApiError } from "../runtime/client";
import type { CreateSpaceRequest } from "../types/CreateSpaceRequest";

type Data = Awaited<ReturnType<typeof createSpaceHandler>>;
type Vars = CreateSpaceRequest;

export function useCreateSpace(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => createSpaceHandler(vars),
    ...options,
  });
}
